import{_ as n,C as e,o as s,c as l,j as i,E as o,a as r,a3 as d}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"1-hafta (Mentor)","description":"","frontmatter":{"title":"1-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"11-sinf","link":"/mentor/11-sinf/"},"n":1,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":1,"title":"IT ekotizimi qatlamlari, SDLC bosqichlari va jamoadagi rollar","lead":"Siz har kuni ishlatadigan ilova ortida ko'zga ko'rinmaydigan butun bir «shahar» bor: qatlamlar, serverlar va jamoa. Bugun uni xaritaga tushiramiz va o'z portfolio-loyihangiz uchun birinchi professional hujjatni yozamiz.","link":"/mentor/11-sinf/hafta-01/dars-1","slide":"/slaydlar/11-sinf/hafta-01/dars-1.html","test":"/slaydlar/11-sinf/hafta-01/dars-1-test.html"},{"g":2,"title":"Git asoslari: versiyalarni boshqarish, repozitoriy, commit, branch va merge","lead":"Bugun siz kodingiz uchun «vaqt mashinasi» yasaysiz: terminalda birinchi repozitoriyni yaratib, har o'zgarishni saqlaysiz, parallel shox ochasiz va konfliktni yechasiz. Professional dasturchilar har kuni shu buyruqlar bilan ishlaydi.","link":"/mentor/11-sinf/hafta-01/dars-2","slide":"/slaydlar/11-sinf/hafta-01/dars-2.html","test":"/slaydlar/11-sinf/hafta-01/dars-2-test.html"},{"g":3,"title":"GitHub: masofaviy repo, push/pull/clone, README, .gitignore, Issues va birinchi loyiha","lead":"Bugun kodingiz birinchi marta noutbukdan chiqib, butun dunyo ko'ra oladigan joyga boradi: GitHub. Oxirida sizda ish beruvchiga ko'rsatsa bo'ladigan birinchi haqiqiy repo bo'ladi.","link":"/mentor/11-sinf/hafta-01/dars-3","slide":"/slaydlar/11-sinf/hafta-01/dars-3.html","test":"/slaydlar/11-sinf/hafta-01/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"mentor/11-sinf/hafta-01/index.md","filePath":"mentor/11-sinf/hafta-01/index.md"}`),h={name:"mentor/11-sinf/hafta-01/index.md"},c={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},g={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function b(_,a,k,y,v,q){const t=e("Icon");return s(),l("div",null,[i("div",c,[i("h2",m,[o(t,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Parol, token, maxfiy kalit va shaxsiy ma&#39;lumotlarni hech kimga yubormang va fayllarga yozmang: topshirishda faqat fayl yoki ochiq repo havolasi kerak.</p><h2 id="_1-dars-uchun-it-ekotizimi-va-sdlc" tabindex="-1">1-dars uchun (IT ekotizimi va SDLC) <a class="header-anchor" href="#_1-dars-uchun-it-ekotizimi-va-sdlc" aria-label="Permalink to &quot;1-dars uchun (IT ekotizimi va SDLC)&quot;">​</a></h2><p><strong>1-topshiriq: «Portfolio-loyiha: talab»</strong></p><ol><li>Darsda boshlagan <code>SRS-mini.md</code> faylini yakunlang. Unda bo&#39;lishi kerak: bir jumlalik maqsad; 5 ta user story; har bir user story uchun kamida 2 ta qabul mezoni; «loyiha nimani qilmaydi» bo&#39;limida 3 ta cheklov.</li><li>Qabul mezonlarini o&#39;lchanadigan qilib yozing: «chiroyli», «tez» kabi mavhum so&#39;zlar o&#39;rniga son yoki tekshiriladigan shart yozing.</li><li>Sevimli ilovangizning 4 qatlamli xaritasini (klient, ilova, platforma, infratuzilma) toza chizing: har qatlamda kamida 2 ta komponent bo&#39;lsin. Rasm yoki foto qiling.</li><li>Terminalda <code>git --version</code> buyrug&#39;ini ishga tushiring va natijani tekshiring: keyingi darsda Git bilan ishlaymiz.</li></ol><p><strong>Kutiladigan natija:</strong> <code>SRS-mini.md</code> (5 user story, 10 dan ortiq o&#39;lchanadigan qabul mezoni, 3 cheklov); ilova xaritasining rasmi; <code>git --version</code> versiya raqamini chiqaradi. <strong>Topshirish:</strong> <code>SRS-mini.md</code> fayli, xarita rasmi va <code>git --version</code> natijasining skrinshoti yoki ko&#39;chirilgan matni.</p><h2 id="_2-dars-uchun-git-asoslari-commit-branch-merge" tabindex="-1">2-dars uchun (Git asoslari: commit, branch, merge) <a class="header-anchor" href="#_2-dars-uchun-git-asoslari-commit-branch-merge" aria-label="Permalink to &quot;2-dars uchun (Git asoslari: commit, branch, merge)&quot;">​</a></h2><p><strong>2-topshiriq: <code>dev-journal</code> ni boyiting</strong></p><ol><li><code>dev-journal</code> repozitoriyasida <code>.gitignore</code> faylini yarating. Unda kamida <code>.env</code> va <code>__pycache__/</code> qatorlari bo&#39;lsin.</li><li>Uch kun uchun <code>notes/kun-1.md</code>, <code>notes/kun-2.md</code>, <code>notes/kun-3.md</code> yozuvlarini yozing. Har bir fayl alohida commit bo&#39;lsin, xabarlar Conventional Commits uslubida (masalan, <code>docs: ...</code>).</li><li><code>feature/skills</code> shoxini oching, unda bitta o&#39;zgarish qiling va commit qiling, so&#39;ng uni <code>main</code> ga merge qiling.</li><li><code>git log --oneline --graph</code> natijasini <code>log.txt</code> fayliga saqlang va shu faylni ham commit qiling.</li></ol><p><strong>Kutiladigan natija:</strong> <code>git log</code> da 3 ta kunlik yozuv commiti, <code>.gitignore</code> commiti, merge va <code>log.txt</code> commiti ko&#39;rinadi; grafikda <code>feature/skills</code> shoxi <code>main</code> ga qo&#39;shilgani bilinadi; <code>git status</code> toza. <strong>Topshirish:</strong> <code>log.txt</code> fayli va <code>git status</code> natijasi. Keyingi darsda bu repoz GitHub&#39;ga yuklanadi.</p><h2 id="_3-dars-uchun-github" tabindex="-1">3-dars uchun (GitHub) <a class="header-anchor" href="#_3-dars-uchun-github" aria-label="Permalink to &quot;3-dars uchun (GitHub)&quot;">​</a></h2><p><strong>3-topshiriq: <code>dev-log</code> ni davom ettiring</strong></p><ol><li>Darsda yaratgan <code>dev-log</code> repongizga yana 2 ta mazmunli commit qo&#39;shing (masalan, <code>todo.py</code> ga yangi buyruq va <code>README.md</code> ni yaxshilash). Commit xabari nima o&#39;zgarganini aniq aytsin.</li><li>GitHub&#39;da bitta Issue oching va uni commit xabaridagi <code>Closes #N</code> (o&#39;z Issue raqamingiz) orqali yoping.</li><li>O&#39;zgarishlarni <code>git push</code> bilan GitHub&#39;ga yuboring va repo ochiq (public) ekanini tekshiring.</li><li>Repo havolasini mentorga yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> GitHub&#39;dagi <code>dev-log</code> da yangi 2 ta commit; Issue <code>Closed</code> holatida va uni yopgan commitga havola bor; <code>README.md</code> va <code>.gitignore</code> joyida; repo havolasi brauzerda (kirmasdan) ochiladi. <strong>Topshirish:</strong> faqat ochiq repo havolasi (<code>https://github.com/&lt;nom&gt;/dev-log</code>). Parol, token yoki kalit yubormang.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><ul><li>1-dars: mavhum mezonlarni («tez», «qulay») qaytaring, son va tekshiriladigan shart so&#39;rang. Xaritada komponent noto&#39;g&#39;ri qatlamga qo&#39;yilgan bo&#39;lsa (masalan, DB klientda), tuzatishni o&#39;quvchining o&#39;ziga topdiring.</li><li>2-dars: <code>log.txt</code> da grafik (<code>*</code>, <code>|</code>) haqiqatan bor-yo&#39;qligini va commit xabarlari uslubini tekshiring. Hash&#39;lar har kimda boshqacha bo&#39;lishi tabiiy. Merge fast-forward bo&#39;lsa, grafik tekis chiqadi: bu xato emas, lekin shox mavjudligini <code>git branch</code> yoki xabarlardan tekshiring.</li><li>3-dars: havolani brauzerda oching, Issue yopilgan-yopilmaganini va yopgan commitni ko&#39;ring. <code>.env</code>, kalit yoki token repoga tushib qolmaganini tekshiring; tushgan bo&#39;lsa, darhol kalitni almashtirishni va tarixdan tozalashni tushuntiring. Parol/tokenni so&#39;ramang.</li><li>Keyingi dars boshida (10 daqiqa) 1–2 ta ishni ekranda ko&#39;rib chiqing, xatolarni o&#39;quvchining o&#39;zi topsin.</li><li>Kechikkan yoki to&#39;liq bo&#39;lmagan vazifani rad etmang: nima yetishmasligini aytib, qayta topshirishga imkon bering va baholashda dinamikani yozib boring.</li></ul>',15))]),i("div",g,[i("h2",u,[o(t,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=d('<p>Bitta o&#39;quvchi uchun shablon. Maqsad: haftalar bo&#39;yicha o&#39;sish dinamikasini kuzatish. Har hafta shu shablon nusxalanib, «Dinamika» jadvaliga bitta qator qo&#39;shiladi.</p><p><strong>O&#39;quvchi:</strong> ____________________ <strong>Guruh/sinf:</strong> 11-sinf <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" tabindex="-1">Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim) <a class="header-anchor" href="#shkala-va-mezonlar-o-quv-dasturi-8-bo-lim" aria-label="Permalink to &quot;Shkala va mezonlar (o&#39;quv dasturi, 8-bo&#39;lim)&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><p>Dasturdagi mezonlar: mavzu bo&#39;yicha tasavvurga ega bo&#39;lish; mavzu mohiyatini tushunish va aytib bera olish; bilimni amalda qo&#39;llash; ijodiy fikrlash va xulosa chiqarish; mustaqil ish bajarish. 5 baho uchun mustaqil xulosa va qaror qabul qilish ham talab etiladi; 3 baho uchun bilimni amalda qo&#39;llay olish yetarli.</p><p>Joriy nazorat (so&#39;rovlar va bajarilgan loyiha ishini izohlash) dasturda loyiha ishi uchun 40 ball bilan belgilangan va o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyidagi dars bo&#39;yicha ball taqsimoti dasturda berilmagan, mentor taklif etilgan jadvalni o&#39;zgartirishi mumkin.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Mohiyatni tushunadi va aytib bera oladi (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq: to&#39;g&#39;ri va to&#39;liq, mustaqil bajarilgan</td><td>30</td></tr><tr><td>Ish sifati: toza kod/fayl, aniq commit xabarlari, tartibli tuzilma</td><td>20</td></tr><tr><td>Uyga vazifa bajarilgan va o&#39;z vaqtida topshirilgan</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><p>Qo&#39;shimcha: ijodiy fikrlash va mustaqil xulosa (masalan, qiyin topshiriq) mezonlar doirasida e&#39;tiborga olinadi.</p><h2 id="_1-dars-it-ekotizimi-va-sdlc" tabindex="-1">1-dars. IT ekotizimi va SDLC <a class="header-anchor" href="#_1-dars-it-ekotizimi-va-sdlc" aria-label="Permalink to &quot;1-dars. IT ekotizimi va SDLC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>4 qatlamni misollar bilan aytadi; qatlamlash foydasi; SDLC bosqichlari va rollar</td><td></td></tr><tr><td>Amaliyot /30</td><td>ilova xaritasi (qatlam/komponent to&#39;g&#39;ri); artefaktlarni bosqichga moslash; <code>SRS-mini.md</code> boshlangan</td><td></td></tr><tr><td>Ish sifati /20</td><td>user story shakli to&#39;g&#39;ri; qabul mezonlari o&#39;lchanadigan (mavhum emas)</td><td></td></tr><tr><td>Uyga vazifa /20</td><td><code>SRS-mini.md</code> to&#39;liq (5 story, 10+ mezon, 3 cheklov); xarita rasmi; <code>git --version</code> ishlaydi</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><h2 id="_2-dars-git-asoslari" tabindex="-1">2-dars. Git asoslari <a class="header-anchor" href="#_2-dars-git-asoslari" aria-label="Permalink to &quot;2-dars. Git asoslari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>3 zona (working dir, staging, repo); <code>add</code>/<code>commit</code>; branch va merge nima</td><td></td></tr><tr><td>Amaliyot /30</td><td><code>init</code>, <code>add</code>, <code>commit</code>, <code>status</code>, <code>diff</code>; shox ochish va merge; konfliktni hal qilish (urinish)</td><td></td></tr><tr><td>Ish sifati /20</td><td>commit kichik va mazmunli; Conventional Commits uslubi; <code>.gitignore</code> to&#39;g&#39;ri</td><td></td></tr><tr><td>Uyga vazifa /20</td><td>3 ta kunlik commit; <code>feature/skills</code> merge; <code>log.txt</code> grafik bilan; <code>git status</code> toza</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><h2 id="_3-dars-github" tabindex="-1">3-dars. GitHub <a class="header-anchor" href="#_3-dars-github" aria-label="Permalink to &quot;3-dars. GitHub&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Nimaga qaraladi</th><th>Ball</th></tr></thead><tbody><tr><td>Tezkor nazorat /30</td><td>remote, push/pull/clone, <code>fetch</code> va <code>pull</code> farqi; sirlarni repoga qo&#39;ymaslik</td><td></td></tr><tr><td>Amaliyot /30</td><td>repo yaratilgan va ulangan; <code>push -u origin main</code>; xavfsiz autentifikatsiya (SSH/token) sozlangan</td><td></td></tr><tr><td>Ish sifati /20</td><td><code>README.md</code> mazmunli; <code>.gitignore</code> bor; Issue aniq yozilgan</td><td></td></tr><tr><td>Uyga vazifa /20</td><td>2 ta yangi commit; Issue <code>Closes #N</code> bilan yopilgan; ochiq repo havolasi yuborilgan, maxfiy ma&#39;lumot yo&#39;q</td><td></td></tr><tr><td><strong>Jami /100</strong></td><td></td><td></td></tr></tbody></table><p>Izoh: ____________________</p><h2 id="hafta-yakuni" tabindex="-1">Hafta yakuni <a class="header-anchor" href="#hafta-yakuni" aria-label="Permalink to &quot;Hafta yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ko&#39;rsatkich</th><th>1-dars</th><th>2-dars</th><th>3-dars</th><th>O&#39;rtacha</th><th>Baho</th></tr></thead><tbody><tr><td>Ball</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Kuchli tomonlari:</strong> ____________________</p><p><strong>Rivojlantirish kerak:</strong> ____________________</p><p><strong>Mustaqillik darajasi</strong> (yordamsiz / ishora bilan / bosqichma-bosqich yordam): ____________________</p><h2 id="dinamika-haftalar-bo-yicha-har-hafta-bitta-qator-qo-shiladi" tabindex="-1">Dinamika (haftalar bo&#39;yicha, har hafta bitta qator qo&#39;shiladi) <a class="header-anchor" href="#dinamika-haftalar-bo-yicha-har-hafta-bitta-qator-qo-shiladi" aria-label="Permalink to &quot;Dinamika (haftalar bo&#39;yicha, har hafta bitta qator qo&#39;shiladi)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hafta</th><th>Mavzu</th><th>O&#39;rtacha ball</th><th>Baho</th><th>O&#39;tgan haftaga nisbatan (↑ / = / ↓)</th><th>Asosiy kuzatuv</th></tr></thead><tbody><tr><td>1</td><td>IT ekotizimi, SDLC, Git, GitHub</td><td></td><td></td><td>boshlang&#39;ich nuqta</td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Oraliq nazorat chorak oxirida o&#39;tkaziladi va bu haftaga to&#39;g&#39;ri kelmaydi. Shu haftalik ballar joriy nazorat kuzatuvi sifatida saqlanadi.</p><h2 id="hafta-xulosasi-va-2-haftaga-ko-prik" tabindex="-1">Hafta xulosasi va 2-haftaga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-2-haftaga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va 2-haftaga ko&#39;prik&quot;">​</a></h2><p><strong>Bu hafta:</strong> IT ekotizimining qatlamlari, SDLC bosqichlari va jamoadagi rollar; mini-SRS; Git (repozitoriy, commit, shox, merge, <code>log</code>); GitHub (remote, push/pull/clone, README, <code>.gitignore</code>, Issues). O&#39;quvchi birinchi ochiq repo (<code>dev-log</code>) va <code>dev-journal</code> bilan chiqdi.</p><p><strong>Keyingi hafta (2-hafta, 4-dars va undan keyin):</strong> Branching strategiyalari, Pull Request va code review. Bu haftadagi bilimga to&#39;g&#39;ridan-to&#39;g&#39;ri tayanadi: <code>feature/skills</code> shoxi va merge tajribasi branching strategiyasiga, kichik commit va Issue oqimi (issue → feature branch → PR → review → merge) Pull Request&#39;ga asos bo&#39;ladi.</p><p><strong>Mentor uchun keyingi dars oldidan tekshiruv:</strong></p><ul><li>O&#39;quvchida GitHub&#39;ga ishlaydigan autentifikatsiya (SSH yoki token) bormi; <code>push</code> xatosiz o&#39;tadimi?</li><li><code>dev-log</code> va <code>dev-journal</code> GitHub&#39;da bormi? Pull Request mashqi uchun ulardan biri kerak bo&#39;ladi.</li><li>Shox ochish va merge&#39;ni mustaqil bajara oladimi? Zaif bo&#39;lsa, 4-dars boshida 10 daqiqalik takrorlash qo&#39;shing.</li><li>Commit xabarlari va Issue&#39;lar aniqmi? Code review&#39;da ham aniq, hurmatli fikr bildirish talab etiladi.</li></ul>',30))])])}const p=n(h,[["render",b]]);export{z as __pageData,p as default};
